/* Agent Hub 设计 token：取自原型 v7「Dispatch Desk」，明暗两套。 */
:root {
  --font-sans:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', 'PingFang SC', 'Hiragino Sans GB',
    'Noto Sans SC', 'Source Han Sans SC', 'Microsoft YaHei', sans-serif;
  --font-mono:
    ui-monospace, 'SF Mono', 'JetBrains Mono', 'Cascadia Mono', 'Roboto Mono', Menlo, Consolas,
    monospace;

  --paper: #f0efe8;
  --paper-2: #e9e7dd;
  --surface: #fbfaf5;
  --surface-2: #f4f3ec;
  --ink: #141b20;
  --ink-2: #4f5b63;
  --ink-3: #5a656c;
  --line: #d7d5c9;
  --line-2: #e3e1d6;

  --prussian: #17465e;
  --prussian-soft: #e4ecef;
  --amber: #a9741f;
  --amber-text: #8a5d14;
